param([ValidateSet('build','test','q7169','q8192')][string]$Action='build')
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=[Text.UTF8Encoding]::new($false)
if(-not [Environment]::MachineName.Equals('baiying',[StringComparison]::OrdinalIgnoreCase)){throw 'Requires baiying'}
$repo='D:\projects\AIMA-public-microtile-exact-qk-20260917';$seed='D:\projects\AIMA-public-register-pv-provider-20260917';$sha='cbe357d7f1e82fc3ce592251a6f45979c388cd53';$bundle='D:\projects\microtile-exact-qk-cbe357d.bundle'
function Verify-File([string]$Path,[string]$Hash){if((Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant() -ne $Hash){throw ('Changed input: '+$Path)}}
Verify-File $bundle '4a25a17e07314b0affe5d4d27ff6a71f349d501e390c7694783262bb198ca27e'
if(-not (Test-Path $repo)){
 & git -C $seed fetch $bundle HEAD;if($LASTEXITCODE -ne 0){throw 'Fetch failed'}
 & git -C $seed worktree add --detach $repo $sha;if($LASTEXITCODE -ne 0){throw 'Worktree creation failed'}
}
if((& git -C $repo rev-parse HEAD).Trim() -ne $sha -or @(& git -C $repo status --porcelain).Count -ne 0){throw 'Source mismatch'}
$build=Join-Path $repo 'build\microtile-exact-qk';$null=New-Item -ItemType Directory -Path $build -Force
$source=Join-Path $repo 'tests\native\microtile_exact_qk_selftest.cpp'
$exe=Join-Path $build 'microtile-exact-qk.exe';$provenance=Join-Path $build 'build-provenance.json'
$sourceFiles=@($source,(Join-Path $repo 'native\providers\sm121_attention_capacity.h'))
foreach($dir in @('native\providers\moe_accumulator','native\providers\gdn','native\providers\ck_fmha','tests\native')){
 $sourceFiles+=@(Get-ChildItem (Join-Path $repo $dir) -Filter '*.h' -File|ForEach-Object {$_.FullName})
}
$sourceInputs=@($sourceFiles|Sort-Object -Unique|ForEach-Object {@{file=$_;sha256=(Get-FileHash $_ -Algorithm SHA256).Hash.ToLowerInvariant()}})
$spec=[ordered]@{executable='';arguments=@();working_directory=$repo;repo_commit=$sha;command_file=$PSCommandPath;command_file_sha256=(Get-FileHash $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();source_inputs=$sourceInputs;model='none; isolated shared per-thread QK score inputs with complete original fallback';model_loaded=$false;inference_acceptance=$false;performance_acceptance=$false;product_dispatch_changed=$false;purpose='Compare original retained and deferred QK controls with exact scalar schedules owning1x2,2x1 or2x2 score cells per thread. Amortize cooperative Q/K staging and share decoded query operands across key cells. Every cell retains original K16 exponent maxima, exact products, modulo sums, normalization and ascending carry order. Reject only the affected cell and include its complete original fallback scan. Verify every generated/captured raw score, independent CPU samples, immutable original/prepared inputs, complete unused tails and guards. q8192 repeats1023 original capture rows; this supplies no new model tokens or GB10 boundary. No dispatcher, numerical threshold or package changes.'}
$env:PATH='C:\Program Files\AMD\ROCm\7.1\bin;'+$env:PATH
if($Action.StartsWith('build')){
 $link=Join-Path $build 'hipblaslt.lib';Copy-Item 'C:\Program Files\AMD\ROCm\7.1\lib\libhipblaslt.dll.a' $link
 $spec.link_inputs=@(@{file=$link;sha256=(Get-FileHash $link -Algorithm SHA256).Hash.ToLowerInvariant()})
 $spec.executable='C:\Program Files\AMD\ROCm\7.1\bin\hipcc.exe'
 $spec.arguments=@('-std=c++17','-O3','-DQRT_SM121_DPP_REDUCTION=1','-DQRT_SM121_COMPACT_NORMALIZE=1','-DQRT_CK_SM121_INTERPOLATED_EXP2=1','--offload-arch=gfx1151','-L',$build,$source,'-o',$exe,'-lhipblaslt');$timeout=180
}else{
 $meta=[IO.File]::ReadAllText($provenance)|ConvertFrom-Json
 if($meta.repo_commit -ne $sha){throw 'Build commit mismatch'}
 Verify-File $exe $meta.executable.sha256
 foreach($file in $meta.source_inputs){Verify-File $file.file $file.sha256}
 $spec.build_provenance_sha256=(Get-FileHash $provenance -Algorithm SHA256).Hash.ToLowerInvariant()
 $spec.executable=$exe;$spec.arguments=@('--selftest');$timeout=240
 if($Action -eq 'q7169' -or $Action -eq 'q8192'){
  $capRoot='D:\projects\AIMA-public-fa-out-20260911\build\fla-model-q7169-fa-out-r1'
  $q=Join-Path $capRoot 'layer3-full-full_attention_q_norm_rope-bf16.bin';$k=Join-Path $capRoot 'layer3-full-full_attention_k_norm_rope-bf16.bin'
  $inputs=@(@{file=$q;sha256='c04de09df4879842e299db9822c76e0b6e13a70c345cb9803d74722e25f24b7d'},@{file=$k;sha256='99bd880e732fd2786c12a68113fe5f834b5cc0fe87b09b0aaf5734c90bf3f2e8'})
  foreach($file in $inputs){Verify-File $file.file $file.sha256}
  $spec.input_files=$inputs;$spec.arguments=@(('--'+$Action),$q,$k)
  $spec.model='D:\models\Qwen3.6-35B-A3B; original captured q7169 layer3 QK; q8192 repeats the first1023 captured rows as a component extension'
  $spec.model_index_sha256='41b9356101ebf8e7519e150dc811f80c4226e727301fbb032b890f006ed0be83';$spec.input_run_sha256='4a4334d65056371866a10626bec395f9778a2cb6a182ead0560c35ea5cb20146';$spec.input_whole_source='28c4f9df501e8e95ac357acc45d30daf48633bf8'
  $spec.real_model_prompt=$false;$spec.reference_is_compute_input=$false
 }

}
$out=Join-Path $repo ('build\microtile-exact-qk-'+$Action+'-r1');$specPath=Join-Path $build ($Action+'-spec-r1.json')
if((Test-Path $out) -or (Test-Path $specPath)){throw 'Evidence already exists'}
[IO.File]::WriteAllText($specPath,($spec|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
& (Join-Path $repo 'scripts\baiying_guarded_inference.ps1') -SpecPath $specPath -OutDir $out -TimeoutSeconds $timeout|Out-Null
$r=[IO.File]::ReadAllText((Join-Path $out 'run-record.json'))|ConvertFrom-Json
$r|Select-Object reason,exit_code,wall_ms,host_checks|ConvertTo-Json -Depth 5
foreach($name in @('product.stdout.jsonl','product.stderr.log')){Get-Content (Join-Path $out $name) -Tail 8|ForEach-Object {$_.Substring(0,[Math]::Min(2000,$_.Length))}}
if($r.reason -ne 'completed' -or $r.exit_code -ne 0 -or -not $r.host_checks_pass){throw 'Native diagnostic action failed'}
if($Action.StartsWith('build')){
 $meta=[ordered]@{host=[Environment]::MachineName;repo_commit=$sha;source_inputs=$sourceInputs;command_file=$PSCommandPath;command_file_sha256=$spec.command_file_sha256;compiler=$spec.executable;arguments=$spec.arguments;link_inputs=$spec.link_inputs;run_record_sha256=(Get-FileHash (Join-Path $out 'run-record.json') -Algorithm SHA256).Hash.ToLowerInvariant();executable=@{file=$exe;bytes=(Get-Item $exe).Length;sha256=(Get-FileHash $exe -Algorithm SHA256).Hash.ToLowerInvariant()}}
 [IO.File]::WriteAllText($provenance,($meta|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false))
}else{
 $reports=@([IO.File]::ReadAllLines((Join-Path $out 'product.stdout.jsonl'))|Where-Object {$_.StartsWith('{')}|ForEach-Object {$_|ConvertFrom-Json})
  $expected=if($Action -eq 'test'){120}else{5}
  if($reports.Count -ne $expected){throw 'Incomplete QK reports'}
  foreach($r in $reports){if($r.raw_bit_mismatches -ne 0 -or -not $r.redzones_pass -or -not $r.immutable_inputs){throw 'QK numerical or memory comparison failed'}}
 foreach($file in $spec.input_files){Verify-File $file.file $file.sha256}
}
